function even_odd_count(num){
  let countEven = 0;
  let countOdd = 0;
  num = Math.abs(num); // Convert to positive for simplicity
  while (num > 0) {
    let digit = num % 10;
    if (digit % 2 === 0) {
      countEven++;
    } else {
      countOdd++;
    }
    num = Math.floor(num / 10);
  }
  return [countEven, countOdd];
}

