function text_match_wordz_middle(text){
    // Ensure the string is not a single character long
    if (text.length <= 1) return false;

    // Ensure 'z' is not the first or last character of the string
    if (text.charAt(0) === 'z' || text.charAt(text.length - 1) === 'z') return false;

    // Check if 'z' is in the middle of the string
