  }

  let maxLength = 0;
  let longestString = "";

  for (let i = 0; i < strings.length; i++) {
    const str = strings[i];
    const len = str.length;

    if (len > maxLength) {
      maxLength = len;
      longestString = str;
    }
  }

  return longestString;
}

function prod_signs(arr) {
  if (arr.length === 0) return undefined;

  let productOfSigns = 1;
  let sumOfMagnitudes = 0;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === 0) return 0; // Early return for 0

    productOfSigns *= Math.sign(arr[i]); // Multiply by the sign of the current number
    sumOfMagnitudes += Math.abs(arr[i]); // Add the absolute value of the current number
  }

  return productOfSigns * sumOfMagnitudes;
}

