  let maxFreq = 0;

  // Count the frequency of each element
  for (let num of lst) {
    freqMap[num] = (freqMap[num] || 0) + 1;
    if (freqMap[num] > maxFreq) {
      maxFreq = freqMap[num];
    }
  }

  // Find the greatest integer with a frequency greater than or equal to its value
  for (let num in freqMap) {
    if (num <= maxFreq && parseInt(num) === num) {
      return parseInt(num);
    }
  }

  return -1;
}

function find_min_diff(arr, n) {
    arr.sort((a, b) => a - b);
    let min_diff = arr[1] - arr[0];
    for(let i = 2; i < n; i++) {
        min_diff = Math.min(min_diff, arr[i] - arr[i-1]);
    }
    return min_diff;
}

