function closest_integer(value) {
    const num = parseFloat(value);
    const floorValue = Math.floor(num);
    const ceilValue = Math.ceil(num);

    if (num - floorValue === 0.5 || ceilValue - num === 0.5) {
        return Math.sign(num) * Math.ceil(Math.abs(num));
    } else {
